4.1 Demonstrasi pada Tiga Bentuk Populasi

set.seed(3)
pop_bentuk&lt;-list(
"Seragam" = runif(20000,0,10),
"Menjulurkanan" = rexp(20000,rate= 0.5),
"Bimodal" = c(rnorm(10000, 2, 0.8),rnorm(10000, 8, 0.8))
)
ukuran &lt;-c(2,5, 30)
par(mfrow =c(4, 3), mar= c(3, 3, 2.5, 1))
for(nama in names(pop_bentuk)){
hist(pop_bentuk[[nama]],breaks= 40, col= "#9ecae1", border= "white",
main = paste("Populasi:",nama), xlab= "", ylab= "")
}
for(nn in ukuran){
for(nama in names(pop_bentuk)){
rata &lt;-replicate(3000, mean(sample(pop_bentuk[[nama]],nn)))
hist(rata, breaks = 35, col= "#a1d99b",border= "white",
main= paste0(nama, ",n=",nn), xlab= "",ylab= "")
}
}









par(mfrow =c(1, 1), mar= c(5, 4, 4,2)+ 0.1)

Baris pertama adalah populasi;baris berikutnya adalah distribusi sampling ̄𝑥untuk𝑛=2,5,dan 30.Populasi seragam sudah tampak lonceng pada𝑛=5;populasi bimodal masih bergelombang pada𝑛=2 tetapi lonceng pada𝑛=30;populasi menjulur kanan membutuhkan𝑛terbesar untuk menghilangkan kemencengannya.
